/**
 * Agent guide check.
 *
 * Two rules hold the guides in place.
 *
 * 1. The root `AGENTS.md` is generated from `rules/`. A hand edit of the
 *    generated file is lost on the next `rules/link.sh`, so the check builds
 *    the same text here and compares it. `composeRootGuide` mirrors
 *    `rules/link.sh`: the two header lines, then every `NN-name.md` file in
 *    name order, separated by one blank line.
 * 2. Every directory that owns code has its own `AGENTS.md`, because an agent
 *    reads the guide of a directory before it edits under it. A guide stays
 *    short enough to read in full, so it is capped at 80 lines.
 * 3. The reading list of `tools/agent-context.mjs` runs for every guide, so a
 *    guide cannot point at a file that moved away.
 * 4. Each harness reads the context through its own entry: `CLAUDE.md` holds
 *    the import of the root guide and nothing else, and the start skill has
 *    one file under `.agents/` that `.claude/` links to.
 *
 * A separate root permits a disposable negative check without application
 * fixtures, in the same shape as `tools/check-boundaries.mjs`.
 */
import { readdir, readFile, realpath } from 'node:fs/promises';
import { join, resolve } from 'node:path';
import { missingFiles, readingList } from './agent-context.mjs';
import { root } from './workspace.mjs';

/** Every directory that must carry its own guide. */
export const guidedDirectories = [
  'apps/server',
  'apps/web',
  'packages/api-client',
  'packages/api-contract',
  'packages/core',
  'packages/editor',
  'packages/markdown',
  'packages/storage-browser',
  'packages/storage-server',
  'packages/sync',
  'packages/ui',
  'tests',
  'tools/sdk-codegen',
];

/** How many lines one directory guide may hold. */
export const maximumGuideLines = 80;

/** The one content that the Claude Code entry file may hold. */
export const claudeEntry =
  '@AGENTS.md\n\nAGENTS.md is the source of every rule.\n';

/** The change skill, and the link that the second harness reads. */
export const skillFile = '.agents/skills/build-it-right/SKILL.md';
export const skillLink = '.claude/skills/build-it-right/SKILL.md';

/**
 * Checks the skill frontmatter against the Agent Skills rules.
 *
 * @param {string} text
 * @returns {string[]}
 */
export function skillFailures(text) {
  const block = /^---\n([\s\S]*?)\n---\n/.exec(text);
  if (block === null) return [`${skillFile}: no frontmatter block.`];
  const front = block[1] ?? '';
  const name = (/^name:[ \t]*(.*)$/m.exec(front)?.[1] ?? '').trim();
  const description = (
    /^description:[ \t]*(.*)$/m.exec(front)?.[1] ?? ''
  ).trim();
  /** @type {string[]} */
  const failures = [];
  if (!/^[a-z0-9-]{1,64}$/.test(name))
    failures.push(
      `${skillFile}: the name must be lower case letters, numbers and hyphens, up to 64 characters.`,
    );
  if (/anthropic|claude/.test(name))
    failures.push(`${skillFile}: the name must not hold a reserved word.`);
  if (description.length === 0 || description.length > 1024)
    failures.push(
      `${skillFile}: the description must state what the skill does and when to use it, in up to 1024 characters.`,
    );
  if (/\bI \b|you can/.test(description))
    failures.push(`${skillFile}: write the description in the third person.`);
  return failures;
}

/**
 * Builds the root guide from the rule files, exactly as `rules/link.sh` does.
 *
 * @param {{ name: string; text: string }[]} rules
 * @returns {string}
 */
export function composeRootGuide(rules) {
  const header =
    '# Generated by rules/link.sh. Do not edit this file.\n\n' +
    'Edit files in `rules/` and run `rules/link.sh`.\n\n';
  const ordered = [...rules].sort((left, right) =>
    left.name < right.name ? -1 : left.name > right.name ? 1 : 0,
  );
  return header + ordered.map((rule) => rule.text).join('\n');
}

/**
 * Reads the `NN-name.md` rule files of a rules directory.
 *
 * @param {string} rulesDirectory
 * @returns {Promise<{ name: string; text: string }[]>}
 */
export async function readRules(rulesDirectory) {
  const entries = await readdir(rulesDirectory).catch(() => []);
  const names = entries.filter((name) => /^\d\d-.*\.md$/.test(name)).sort();
  return Promise.all(
    names.map(async (name) => ({
      name,
      text: await readFile(join(rulesDirectory, name), 'utf8'),
    })),
  );
}

/** @param {string} text @returns {number} */
function lineCount(text) {
  const lines = text.split('\n');
  return lines.at(-1) === '' ? lines.length - 1 : lines.length;
}

/**
 * Runs the check over one repository tree.
 *
 * @param {string} directory
 * @returns {Promise<number>} The process status.
 */
export async function main(directory) {
  /** @type {string[]} */
  const failures = [];
  const rules = await readRules(join(directory, 'rules'));
  if (rules.length === 0)
    failures.push('rules/: no rule file. The root AGENTS.md has no source.');
  else {
    const actual = await readFile(join(directory, 'AGENTS.md'), 'utf8').catch(
      () => null,
    );
    if (actual === null)
      failures.push('AGENTS.md: missing. Run rules/link.sh to write it.');
    else if (actual !== composeRootGuide(rules))
      failures.push(
        'AGENTS.md: does not match the rules directory. Run rules/link.sh.',
      );
  }
  const entry = await readFile(join(directory, 'CLAUDE.md'), 'utf8').catch(
    () => null,
  );
  if (entry === null)
    failures.push('CLAUDE.md: missing. It imports the root guide.');
  else if (entry !== claudeEntry)
    failures.push('CLAUDE.md: it holds only the import and the one sentence.');
  const skill = await readFile(join(directory, skillFile), 'utf8').catch(
    () => null,
  );
  if (skill === null) failures.push(`${skillFile}: missing.`);
  else failures.push(...skillFailures(skill));
  const [target, linked] = await Promise.all([
    realpath(join(directory, skillFile)).catch(() => null),
    realpath(join(directory, skillLink)).catch(() => null),
  ]);
  if (target === null || linked !== target)
    failures.push(`${skillLink}: it must link to ${skillFile}.`);
  /** @type {Set<string>} */
  const stale = new Set();
  for (const guided of guidedDirectories) {
    const entries = await readingList(directory, [join(directory, guided)]);
    for (const file of await missingFiles(directory, entries)) stale.add(file);
  }
  for (const file of stale)
    failures.push(`${file}: a reading list points here, but the file is gone.`);
  for (const guided of guidedDirectories) {
    const text = await readFile(
      join(directory, guided, 'AGENTS.md'),
      'utf8',
    ).catch(() => null);
    if (text === null) {
      failures.push(`${guided}/AGENTS.md: missing.`);
      continue;
    }
    const count = lineCount(text);
    if (count > maximumGuideLines)
      failures.push(
        `${guided}/AGENTS.md: ${count} lines. Keep it under ${maximumGuideLines}.`,
      );
  }
  if (failures.length > 0) {
    process.stderr.write(
      [
        'Agent guide check failed:',
        ...failures.map((failure) => `  ${failure}`),
      ].join('\n') + '\n',
    );
    return 1;
  }
  process.stdout.write(
    `Agent guides: the root guide matches ${rules.length} rule files, ${guidedDirectories.length} directory guides are present with a complete reading list, and both harness entries resolve.\n`,
  );
  return 0;
}

// The helpers above are imported by the unit test, so the check itself runs
// only when this file is the program.
if (import.meta.main) {
  const args = process.argv.slice(2);
  if (args.length && (args.length !== 2 || args[0] !== '--root')) {
    process.stderr.write(
      'Usage: node tools/check-agents-md.mjs [--root <directory>]\n',
    );
    process.exit(1);
  }
  process.exit(await main(resolve(args[1] ?? root)));
}
